pub open spec fn rsi_vdev_get_info_spec(vdev_id: Bits64, addr: Address, result: RsiCommandReturnCode, old_s: S, new_s: S) -> bool {
    let realm = CurrentRealm(old_s);
    let vdev = VdevFromVdevId(old_s, realm, vdev_id);
    let pdev = PdevAt(old_s, vdev.pdev);
    let cfg = RsiVdevInfoAt(old_s, addr);
    let walk = RttWalk(old_s, realm, addr, RMM_RTT_PAGE_LEVEL as int, RMM_RTT_TREE_PRIMARY as int);
    (
        (realm.feat_da == RMM_FEATURE_FALSE ==> ResultEqual(result, RSI_ERROR_STATE))
        && (VdevIdIsFree(old_s, realm, vdev_id) ==> ResultEqual(result, RSI_ERROR_INPUT))
        && (!AddrIsAligned(old_s, addr, 512) ==> ResultEqual(result, RSI_ERROR_INPUT))
        && (!AddrIsProtected(old_s, addr, realm) ==> ResultEqual(result, RSI_ERROR_INPUT))
        && (walk.rtte.ripas == EMPTY ==> ResultEqual(result, RSI_ERROR_INPUT))
        && (result == RSI_SUCCESS ==> cfg.hash_algo == HashAlgorithmToRsi(pdev.hash_algo))
        && (result == RSI_SUCCESS ==> cfg.flags.p2p_enabled == FeatureToRsi(pdev.p2p_enabled))
        && (result == RSI_SUCCESS ==> cfg.flags.p2p_bound == FeatureToRsi(vdev.p2p_bound))
        && (result == RSI_SUCCESS ==> cfg.p2p_peer == vdev.p2p_peer)
        && (result == RSI_SUCCESS ==> VdevAttestInfoEqual(cfg.lock_nonce, cfg.meas_nonce, cfg.report_nonce, vdev.attest_info))
        && (result == RSI_SUCCESS ==> cfg.vca_digest == pdev.vca_digest)
        && (result == RSI_SUCCESS ==> cfg.meas_digest == vdev.meas_digest)
        && (result == RSI_SUCCESS ==> cfg.report_digest == vdev.report_digest)
        && (result == RSI_SUCCESS ==> cfg.state == VdevStateToRsi(vdev.vdev_state))
    )
}

pub open spec fn rsi_vdev_validate_mapping_spec(vdev_id: Bits64, ipa_base: Address, ipa_top: Address, pa_base: Address, flags: RsiDevMemFlags, lock_nonce: UInt64, meas_nonce: UInt64, report_nonce: UInt64, result: RsiCommandReturnCode, new_ipa_base: Address, response: RsiResponse, old_s: S, new_s: S) -> bool {
    let realm = CurrentRealm(old_s);
    let rec = CurrentRec(old_s);
    let vdev = VdevFromVdevId(old_s, realm, vdev_id);
    (realm.feat_da == RmmFeature::FEATURE_FALSE ==> result == RsiCommandReturnCode::RSI_ERROR_STATE)
    && (VdevIdIsFree(old_s, realm, vdev_id) ==> result == RsiCommandReturnCode::RSI_ERROR_INPUT)
    && (vdev.vdev_state != RmmVdevState::VDEV_LOCKED && vdev.vdev_state != RmmVdevState::VDEV_STARTED ==> result == RsiCommandReturnCode::RSI_ERROR_INPUT)
    && (!AddrIsGranuleAligned(old_s, ipa_base) ==> result == RsiCommandReturnCode::RSI_ERROR_INPUT)
    && (!AddrIsGranuleAligned(old_s, ipa_top) ==> result == RsiCommandReturnCode::RSI_ERROR_INPUT)
    && (!AddrIsGranuleAligned(old_s, pa_base) ==> result == RsiCommandReturnCode::RSI_ERROR_INPUT)
    && (ipa_top <= ipa_base ==> result == RsiCommandReturnCode::RSI_ERROR_INPUT)
    && (!AddrRangeIsProtected(old_s, ipa_base, ipa_top, realm) ==> result == RsiCommandReturnCode::RSI_ERROR_INPUT)
    && (!VdevAttestInfoEqual(lock_nonce as int, meas_nonce as int, report_nonce as int, vdev.attest_info) ==> result == RsiCommandReturnCode::RSI_ERROR_DEVICE)
    && (result == RsiCommandReturnCode::RSI_SUCCESS ==> new_ipa_base == rec.dev_mem_addr)
    && (result == RsiCommandReturnCode::RSI_SUCCESS ==> response == RecDevMemResponseToRsi(old_s, rec))
}

pub open spec fn rsi_version_spec(req: RsiInterfaceVersion, result: RsiCommandReturnCode, lower: RsiInterfaceVersion, higher: RsiInterfaceVersion, old_s: S, new_s: S) -> bool {
    (!RsiVersionIsSupported(old_s, req) && RsiVersionLowerIsSupported(old_s, req) ==> result == RSI_ERROR_INPUT && VersionEqualRsi(lower, RsiVersionHighestBelow(old_s, req)) && VersionEqualRsi(higher, RsiVersionHighest(old_s)))
    && (!RsiVersionIsSupported(old_s, req) && !RsiVersionLowerIsSupported(old_s, req) && RsiVersionHigherIsSupported(old_s, req) ==> result == RSI_ERROR_INPUT && VersionEqualRsi(lower, higher) && VersionEqualRsi(higher, RsiVersionHighest(old_s)))
    && (result == RSI_SUCCESS ==> VersionEqualRsi(lower, req) && VersionEqualRsi(higher, RsiVersionHighest(old_s)))
}
